fn roll_dice(count: Int, sides: Int) -> Vec[Int] {
  let mut results: Vec[Int] = Vec[Int].new();
  let mut seed = 42;
  let mut i = 0;
  while i < count {
    seed = (seed * 1103515245 + 12345) % 2147483648;
    results.push((seed % sides) + 1);
    i += 1;
  };
  results
}

fn sum_rolls(rolls: &Vec[Int]) -> Int {
  let mut total = 0;
  let mut i = 0;
  while i < rolls.len() {
    total += rolls.get(i).unwrap();
    i += 1;
  };
  total
}

fn main() -> Int {
  let rolls = roll_dice(3, 6);
  let mut i = 0;
  while i < rolls.len() {
    io.println(rolls.get(i).unwrap());
    i += 1;
  };
  io.println(sum_rolls(&rolls));
  return 0;
}
